package main

import (
	"crypto/rand"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"golang.org/x/mod/sumdb/note"
)

// The fixture is generated by testdata/signed-notes/generate and verified by
// the registry's TypeScript tests from the same file (one oracle, two
// implementations); see testdata/signed-notes/README.md.
type signedNoteFixture struct {
	Name        string `json:"name"`
	TreeSize    int    `json:"tree_size"`
	RootHashHex string `json:"root_hash_hex"`
	SeedHex     string `json:"seed_hex"`
	KeyHashHex  string `json:"key_hash_hex"`
	PrivateKey  string `json:"private_key"`
	VerifierKey string `json:"verifier_key"`
	NoteBody    string `json:"note_body"`
	SignedNote  string `json:"signed_note"`
}

func loadSignedNoteFixture(t *testing.T) signedNoteFixture {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "signed-notes", "spec-note-v1.json"))
	if err != nil {
		t.Fatalf("read signed-note fixture: %v", err)
	}
	var fixture signedNoteFixture
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatalf("parse signed-note fixture: %v", err)
	}
	return fixture
}

func TestSignedNoteFixtureVerifies(t *testing.T) {
	fixture := loadSignedNoteFixture(t)

	verifier, err := note.NewVerifier(fixture.VerifierKey)
	if err != nil {
		t.Fatalf("verifier key rejected: %v", err)
	}
	if verifier.Name() != fixture.Name {
		t.Fatalf("verifier name = %q, want %q", verifier.Name(), fixture.Name)
	}
	if got := fmt.Sprintf("%08x", verifier.KeyHash()); got != fixture.KeyHashHex {
		t.Fatalf("key hash = %s, want %s", got, fixture.KeyHashHex)
	}

	opened, err := note.Open([]byte(fixture.SignedNote), note.VerifierList(verifier))
	if err != nil {
		t.Fatalf("note.Open: %v", err)
	}
	if opened.Text != fixture.NoteBody {
		t.Fatalf("opened text does not match the fixture body")
	}

	lines := strings.Split(strings.TrimSuffix(fixture.NoteBody, "\n"), "\n")
	if len(lines) != 3 || lines[0] != fixture.Name {
		t.Fatalf("unexpected checkpoint body shape: %q", fixture.NoteBody)
	}
	if lines[1] != fmt.Sprint(fixture.TreeSize) {
		t.Fatalf("tree size line = %q, want %d", lines[1], fixture.TreeSize)
	}
	root, err := hex.DecodeString(fixture.RootHashHex)
	if err != nil {
		t.Fatalf("root hash hex: %v", err)
	}
	if lines[2] != base64.StdEncoding.EncodeToString(root) {
		t.Fatalf("root hash line does not match root_hash_hex")
	}
}

func TestSignedNoteFixtureSignerIsDeterministic(t *testing.T) {
	fixture := loadSignedNoteFixture(t)

	signer, err := note.NewSigner(fixture.PrivateKey)
	if err != nil {
		t.Fatalf("signer key rejected: %v", err)
	}
	signed, err := note.Sign(&note.Note{Text: fixture.NoteBody}, signer)
	if err != nil {
		t.Fatalf("note.Sign: %v", err)
	}
	if string(signed) != fixture.SignedNote {
		t.Fatalf("fixture out of date; regenerate with: cd testdata/signed-notes/generate && go run . > ../spec-note-v1.json")
	}
}

func TestSignedNoteTamperingFailsVerification(t *testing.T) {
	fixture := loadSignedNoteFixture(t)
	verifier, err := note.NewVerifier(fixture.VerifierKey)
	if err != nil {
		t.Fatalf("verifier key rejected: %v", err)
	}
	tampered := strings.Replace(fixture.SignedNote, "\n3\n", "\n4\n", 1)
	if tampered == fixture.SignedNote {
		t.Fatal("tampering did not change the note (fixture shape changed?)")
	}
	if _, err := note.Open([]byte(tampered), note.VerifierList(verifier)); err == nil {
		t.Fatal("tampered note verified; verification is broken")
	}
}

func TestSignedNoteRoundTripWithoutFixture(t *testing.T) {
	name := "signet-hermetic-log"
	skey, vkey, err := note.GenerateKey(rand.Reader, name)
	if err != nil {
		t.Fatalf("GenerateKey: %v", err)
	}
	signer, err := note.NewSigner(skey)
	if err != nil {
		t.Fatalf("NewSigner: %v", err)
	}
	verifier, err := note.NewVerifier(vkey)
	if err != nil {
		t.Fatalf("NewVerifier: %v", err)
	}
	signed, err := note.Sign(&note.Note{Text: name + "\n1\nAAAA\n"}, signer)
	if err != nil {
		t.Fatalf("note.Sign: %v", err)
	}
	opened, err := note.Open(signed, note.VerifierList(verifier))
	if err != nil {
		t.Fatalf("note.Open: %v", err)
	}
	if opened.Text != name+"\n1\nAAAA\n" {
		t.Fatalf("round trip changed the note text")
	}
}
